                            <Stack id="detail-tab-panel-3" data-oods-component="Stack" data-layout="stack" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--ref-space-cluster-default)' }}>
                              <CycleProgressCard id="slot-tab-0-4" data-oods-component="CycleProgressCard" progress={currentPeriodProgress} periodStart={currentPeriodStart} periodEnd={currentPeriodEnd} interval={billingInterval} />
                              <PaymentTimeline id="slot-tab-1-6" data-oods-component="PaymentTimeline" lastPayment={lastPaymentAt} nextPayment={nextPaymentDueAt} paymentStatus={paymentStatus} paymentMethod={paymentMethodType} amount={amount} currency={currency} />
                            </Stack>
                          ) },
                          { ...{"id":"detail-tab-panel-14","label":"Details"}, panel: (
                            <Stack id="detail-tab-panel-14" data-oods-component="Stack" data-layout="stack" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--ref-space-cluster-default)' }}>
                              <StatusBadge id="slot-tab-3-15" data-oods-component="StatusBadge" label="Payment status" status={paymentStatus} />
                              <Text id="slot-tab-4-17" data-oods-component="Text" label="Amount">{amount}</Text>
                            </Stack>
                          ) }
                        ]} />
                      </div>
                      <aside data-sidebar-aside>
                        <Stack id="detail-meta-11" data-oods-component="Stack" data-layout="stack" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--ref-space-cluster-tight)', padding: 'var(--ref-space-inset-default)' }} />
                      </aside>
                    </Card>
            </Stack>
        <div role="group" aria-label="Screen actions" data-oods-screen-actions="screen-detail-13">
          <button type="button" data-oods-action="handleCancel" onClick={() => handleCancel()}>Cancel subscription</button>
          <button type="button" data-oods-action="handleDelete" onClick={() => handleDelete()}>Delete</button>
          <button type="button" data-oods-action="handleEdit" onClick={() => handleEdit()}>Edit</button>
          <button type="button" data-oods-action="handleViewTimeline" onClick={() => handleViewTimeline()}>View timeline</button>
        </div>
      </>
    </>
  );
};
